#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
DATA="$ROOT/axiom0_data"
if [[ ! -f "$DATA/axiom0-secrets.env" ]]; then echo 'Run deploy/linux/install.sh first' >&2; exit 1; fi
set -a
# File is generated by installer with user-only permissions; do not edit with untrusted content.
source "$DATA/axiom0-secrets.env"
set +a
export AXIOM0_DATA_DIR="$DATA"
exec "$ROOT/.venv/bin/python" -m axiom0 --data-dir "$DATA" serve
